  (2080::integer, 16782::integer, 'CGPT-USDT', 'active', (TIMESTAMP '2026-10-01 01:06:33.755' AT TIME ZONE 'UTC'), NULL::timestamptz, 0.02337::numeric, NULL::numeric, 0.02449::numeric, NULL::numeric, NULL, NULL::numeric, NULL::integer, 'single_entry_v1', 21716122::integer)
),
path AS (
  SELECT c.*, d.source AS snapshot_source, d.trajectory_status AS snapshot_trajectory_status,
         d.decision_at AS snapshot_decision_at, d.entry_price AS snapshot_entry_price,
         CASE WHEN c.original_entry_price > 0 THEN c.original_entry_price ELSE c.entry_price END::numeric AS basis_price,
         count(b.id)::integer AS bars_72h,
         min(b.candle_at) AS first_bar_at, max(b.candle_at) AS last_bar_at,
         max(b.high)::numeric AS max_high_72h, min(b.low)::numeric AS min_low_72h,
         count(b.id) FILTER (WHERE c.closed_at IS NOT NULL AND b.candle_at > c.closed_at)::integer AS bars_after_close,
         max(b.high) FILTER (WHERE c.closed_at IS NOT NULL AND b.candle_at > c.closed_at)::numeric AS max_high_postclose,
         min(b.low) FILTER (WHERE c.closed_at IS NOT NULL AND b.candle_at > c.closed_at)::numeric AS min_low_postclose,
         min(b.candle_at) FILTER (WHERE b.high >= (CASE WHEN c.original_entry_price > 0 THEN c.original_entry_price ELSE c.entry_price END) * 1.10) AS first_10_at,
         min(b.candle_at) FILTER (WHERE b.high >= (CASE WHEN c.original_entry_price > 0 THEN c.original_entry_price ELSE c.entry_price END) * 1.20) AS first_20_at,
         min(b.candle_at) FILTER (WHERE b.high >= (CASE WHEN c.original_entry_price > 0 THEN c.original_entry_price ELSE c.entry_price END) * 1.30) AS first_30_at,
         min(b.candle_at) FILTER (WHERE c.closed_at IS NOT NULL AND b.candle_at > c.closed_at AND b.high >= (CASE WHEN c.original_entry_price > 0 THEN c.original_entry_price ELSE c.entry_price END) * 1.10) AS first_10_postclose_at,
         min(b.candle_at) FILTER (WHERE c.closed_at IS NOT NULL AND b.candle_at > c.closed_at AND b.high >= (CASE WHEN c.original_entry_price > 0 THEN c.original_entry_price ELSE c.entry_price END) * 1.20) AS first_20_postclose_at,
         min(b.candle_at) FILTER (WHERE c.closed_at IS NOT NULL AND b.candle_at > c.closed_at AND b.high >= (CASE WHEN c.original_entry_price > 0 THEN c.original_entry_price ELSE c.entry_price END) * 1.30) AS first_30_postclose_at
  FROM cohort c
  JOIN pattern_decision_snapshots d ON d.id = c.snapshot_id AND d.tracked_signal_id = c.id
  LEFT JOIN pattern_backfill_candles b
    ON b.decision_snapshot_id = d.id
   AND b.interval = '15m'
   AND b.candle_at >= d.decision_at
   AND b.candle_at < d.decision_at + interval '72 hours'
   AND b.candle_at <= TIMESTAMPTZ '2026-10-01 04:36:43.459443+00'
  GROUP BY c.id,c.signal_id,c.symbol,c.status,c.detected_at,c.closed_at,c.entry_price,c.original_entry_price,c.peak_price,c.pnl_percent,c.cancel_reason,c.stop_loss_pct,c.policy_version,c.entry_policy_version,c.snapshot_id,d.source,d.trajectory_status,d.decision_at,d.entry_price
)
SELECT p.*,
       CASE WHEN bars_72h=288 THEN 'complete_72h' WHEN bars_72h>0 THEN 'partial_censored' ELSE 'no_bars' END AS path_coverage,
       CASE WHEN basis_price>0 AND max_high_72h IS NOT NULL THEN (max_high_72h/basis_price-1)*100 END AS mfe_72h_pct,
       CASE WHEN basis_price>0 AND min_low_72h IS NOT NULL THEN (min_low_72h/basis_price-1)*100 END AS mae_72h_pct,
       CASE WHEN basis_price>0 AND max_high_postclose IS NOT NULL THEN (max_high_postclose/basis_price-1)*100 END AS postclose_mfe_pct,
       CASE WHEN basis_price>0 AND min_low_postclose IS NOT NULL THEN (min_low_postclose/basis_price-1)*100 END AS postclose_mae_pct
FROM path p ORDER BY id;

