  WHERE d.pattern_key='price_led_momentum' AND d.decision_kind='fired'
)
SELECT COALESCE(embedded_policy,'<unset>') AS embedded_policy,count(*)::integer AS rows,
       count(*) FILTER (WHERE dm IS NOT NULL)::integer AS has_decision_metrics,
       count(*) FILTER (WHERE dm ? 'p24h' AND dm ? 'p3h' AND dm ? 'spotVolMult')::integer AS has_three_core_keys,
       count(*) FILTER (WHERE dm ? 'snf1h' OR dm ? 'snf4h')::integer AS has_netflow_key,
       count(*) FILTER (WHERE dm ? 'cvd15m' AND dm ? 'cvd30m' AND dm ? 'cvd1h' AND dm ? 'cvd4h')::integer AS has_all_cvd_keys,
       count(*) FILTER (WHERE dm->>'p24h' IS NOT NULL AND dm->>'p3h' IS NOT NULL AND dm->>'spotVolMult' IS NOT NULL AND (dm->>'snf1h' IS NOT NULL OR dm->>'snf4h' IS NOT NULL) AND dm->>'cvd15m' IS NOT NULL AND dm->>'cvd30m' IS NOT NULL AND dm->>'cvd1h' IS NOT NULL AND dm->>'cvd4h' IS NOT NULL)::integer AS all_required_values
FROM x GROUP BY 1 ORDER BY 1;

-- 3) Raw rejected/blocked event inventory; trajectory_status may be backfilled asynchronously.
WITH x AS (
 SELECT d.decision_kind,
  CASE WHEN d.decision_reason LIKE 'p24h_low%' THEN 'p24h_low' WHEN d.decision_reason LIKE 'p24h_high%' THEN 'p24h_high'
       WHEN d.decision_reason LIKE 'p24h_range=%' THEN 'legacy_unstamped_p24h_range' WHEN d.decision_reason LIKE 'p3h_low%' THEN 'p3h_low'
       WHEN d.decision_reason LIKE 'p3h_high%' THEN 'p3h_high' WHEN d.decision_reason LIKE 'spot_vol_low%' THEN 'spot_vol_low'
       WHEN d.decision_reason LIKE 'spot_vol_unavailable%' THEN 'spot_vol_unavailable' WHEN d.decision_reason LIKE 'snf_negative_1h%' THEN 'snf_negative_1h'
       WHEN d.decision_reason LIKE 'cvd_count_%' THEN 'cvd_count_lt2' WHEN d.decision_reason LIKE 'confirmed_fire_%' THEN 'confirmed_fire_other'
       ELSE COALESCE(d.decision_reason,'null') END AS reason_group,d.trajectory_status,d.entry_price,d.entry_metrics
 FROM pattern_decision_snapshots d WHERE d.pattern_key='price_led_momentum' AND d.source='scanner_sym_reject'
   AND d.decision_kind IN ('rejected','blocked') AND d.decision_at<TIMESTAMPTZ '2026-10-01 04:36:43.459443+00'
)
SELECT decision_kind,reason_group,trajectory_status,count(*)::integer AS event_count,
 count(*) FILTER (WHERE entry_price>0)::integer AS rows_with_positive_entry_price,
 count(*) FILTER (WHERE entry_metrics ? 'p24h')::integer AS has_p24h_key,count(*) FILTER (WHERE entry_metrics ? 'p3h')::integer AS has_p3h_key,
 count(*) FILTER (WHERE entry_metrics ? 'spotVolMult')::integer AS has_spotvol_key,
 count(*) FILTER (WHERE entry_metrics ? 'snf1h' OR entry_metrics ? 'snf4h')::integer AS has_netflow_key,
 count(*) FILTER (WHERE entry_metrics ? 'cvdCount')::integer AS has_cvd_key
FROM x GROUP BY 1,2,3 ORDER BY 1,2,3;

-- 3b) Verify that the legacy p24h_range reason cohort has no nested decision-time gate metrics.
SELECT count(*)::integer AS rows,
       count(*) FILTER (WHERE entry_metrics ? 'decision_metrics')::integer AS has_nested_decision_metrics,
       count(*) FILTER (WHERE entry_metrics->'decision_metrics' ? 'p24h')::integer AS nested_p24h,
       count(*) FILTER (WHERE entry_metrics->'decision_metrics' ? 'p3h')::integer AS nested_p3h,
       count(*) FILTER (WHERE entry_metrics->'decision_metrics' ? 'spotVolMult')::integer AS nested_spotvol,
       count(*) FILTER (WHERE entry_metrics->'decision_metrics' ? 'snf1h' OR entry_metrics->'decision_metrics' ? 'snf4h')::integer AS nested_netflow,
       count(*) FILTER (WHERE entry_metrics->'decision_metrics' ? 'cvd15m')::integer AS nested_cvd
FROM pattern_decision_snapshots
WHERE pattern_key='price_led_momentum' AND source='scanner_sym_reject'
  AND decision_kind='rejected' AND decision_reason LIKE 'p24h_range=%'
  AND decision_at<TIMESTAMPTZ '2026-10-01 04:36:43.459443+00';

-- 4) Distinct symbol-UTC-day counts and earliest valid (positive-price) event per day.
WITH raw AS (
 SELECT d.id,d.symbol,d.decision_kind,d.decision_reason,d.decision_at,d.entry_price,d.trajectory_status,
  (d.decision_at AT TIME ZONE 'UTC')::date AS utc_day,
  CASE WHEN d.decision_reason LIKE 'p24h_range=%' THEN 'legacy_unstamped_p24h_range' WHEN d.decision_reason LIKE 'p24h_low%' THEN 'p24h_low'
       WHEN d.decision_reason LIKE 'p24h_high%' THEN 'p24h_high' WHEN d.decision_reason LIKE 'p3h_low%' THEN 'p3h_low'
       WHEN d.decision_reason LIKE 'p3h_high%' THEN 'p3h_high' WHEN d.decision_reason LIKE 'spot_vol_low%' THEN 'spot_vol_low'
       WHEN d.decision_reason LIKE 'spot_vol_unavailable%' THEN 'spot_vol_unavailable' WHEN d.decision_reason LIKE 'snf_negative_1h%' THEN 'snf_negative_1h'
       WHEN d.decision_reason LIKE 'cvd_count_%' THEN 'cvd_count_lt2' WHEN d.decision_reason LIKE 'confirmed_fire_%' THEN 'confirmed_fire_other'
       ELSE COALESCE(d.decision_reason,'null') END AS reason_group
 FROM pattern_decision_snapshots d WHERE d.pattern_key='price_led_momentum' AND d.source='scanner_sym_reject'
  AND d.decision_kind IN ('rejected','blocked') AND d.decision_at<TIMESTAMPTZ '2026-10-01 04:36:43.459443+00'
), day_rollup AS (SELECT symbol,utc_day,bool_or(COALESCE(entry_price>0,FALSE)) AS any_positive_price FROM raw GROUP BY 1,2),
earliest_priced AS (SELECT DISTINCT ON (symbol,utc_day) * FROM raw WHERE entry_price>0 ORDER BY symbol,utc_day,decision_at,id)
SELECT (SELECT count(*) FROM raw)::integer AS raw_events,(SELECT count(DISTINCT symbol) FROM raw)::integer AS unique_symbols,
 (SELECT count(*) FROM day_rollup)::integer AS unique_symbol_utc_days,
 (SELECT count(*) FROM day_rollup WHERE any_positive_price)::integer AS symbol_days_with_positive_price,
 (SELECT count(*) FROM day_rollup WHERE NOT any_positive_price)::integer AS symbol_days_without_positive_price;

WITH raw AS (
 SELECT d.id,d.symbol,d.decision_kind,d.decision_reason,d.decision_at,d.entry_price,d.trajectory_status,
  (d.decision_at AT TIME ZONE 'UTC')::date AS utc_day,
  CASE WHEN d.decision_reason LIKE 'p24h_range=%' THEN 'legacy_unstamped_p24h_range' WHEN d.decision_reason LIKE 'p24h_low%' THEN 'p24h_low'
       WHEN d.decision_reason LIKE 'p24h_high%' THEN 'p24h_high' WHEN d.decision_reason LIKE 'p3h_low%' THEN 'p3h_low'
       WHEN d.decision_reason LIKE 'p3h_high%' THEN 'p3h_high' WHEN d.decision_reason LIKE 'spot_vol_low%' THEN 'spot_vol_low'
       WHEN d.decision_reason LIKE 'spot_vol_unavailable%' THEN 'spot_vol_unavailable' WHEN d.decision_reason LIKE 'snf_negative_1h%' THEN 'snf_negative_1h'
       WHEN d.decision_reason LIKE 'cvd_count_%' THEN 'cvd_count_lt2' WHEN d.decision_reason LIKE 'confirmed_fire_%' THEN 'confirmed_fire_other'
       ELSE COALESCE(d.decision_reason,'null') END AS reason_group
 FROM pattern_decision_snapshots d WHERE d.pattern_key='price_led_momentum' AND d.source='scanner_sym_reject'
  AND d.decision_kind IN ('rejected','blocked') AND d.decision_at<TIMESTAMPTZ '2026-10-01 04:36:43.459443+00'
), earliest_priced AS (SELECT DISTINCT ON (symbol,utc_day) * FROM raw WHERE entry_price>0 ORDER BY symbol,utc_day,decision_at,id)
SELECT decision_kind,reason_group,trajectory_status,count(*)::integer AS earliest_priced_symbol_days,
 count(DISTINCT symbol)::integer AS symbols,min(utc_day) AS first_day,max(utc_day) AS last_day
FROM earliest_priced GROUP BY 1,2,3 ORDER BY 1,2,3;
